from music21 import stream, note, chord, instrument, tempo, meter, key, dynamics, expressions, metadata

# ---------- helpers ----------
def N(midi_num, ql):
    x = note.Note()
    x.pitch.midi = midi_num
    x.duration.quarterLength = ql
    return x

def R(ql):
    r = note.Rest()
    r.duration.quarterLength = ql
    return r

# ---------- harmonic plan: 26 bars of 4/4 ----------
# A (1-8): Dm9 world, waves. B (9-16): brighter, reaching.
# A' (17-22): stripped back, cello sings. Coda (23-26): letting go.
DM7     = [50, 53, 57, 60]
BBMAJ7  = [46, 50, 53, 57]
FMAJ7   = [53, 57, 60, 64]
C7      = [48, 52, 55, 59]
GM7     = [43, 46, 50, 53]
A7      = [45, 49, 52, 55]
DMADD9  = [50, 53, 57, 64]
BB6     = [46, 50, 53, 55]

prog = [DM7, BBMAJ7, FMAJ7, C7, DM7, BBMAJ7, GM7, A7,        # bars 1-8
        FMAJ7, C7, DM7, BB6, GM7, C7, FMAJ7, A7,             # bars 9-16
        DM7, BBMAJ7, GM7, A7, DM7, BBMAJ7,                   # bars 17-22
        DMADD9, GM7, A7, DMADD9]                             # bars 23-26

TOTAL_BARS = 26

# ---------- violin: the voice that remembers ----------
violin_line = {
    5:  [(69, 2), (74, 2)],            # A4 -> D5, first words
    6:  [(72, 2), (77, 1), (76, 1)],   # C5, F5, E5 (the Lydian ache over Bb)
    7:  [(74, 4)],
    8:  [(76, 4)],
    9:  [(81, 2), (79, 2)],            # A5, G5
    10: [(79, 4)],
    11: [(81, 2), (77, 2)],
    12: [(77, 1), (79, 1), (82, 2)],   # reaching up to Bb5
    13: [(82, 2), (81, 2)],            # the peak
    14: [(82, 2), (79, 2)],
    15: [(81, 2), (79, 2)],            # letting the peak fall
    16: [(76, 4)],                     # a breath over the dominant
    19: [(74, 2), (72, 2)],            # a small answer to the cello
    20: [(73, 4)],                     # C#5, suspended
    23: [(76, 4)],                     # E5: the added ninth, a color of goodbye
    24: [(74, 4)],
    25: [(73, 4)],
    26: [(74, 4)],                     # final D, held past its end
}

# ---------- cello: takes over the melody in A' ----------
cello_melody = {
    17: [(53, 1), (57, 1), (62, 2)],   # F3, A3, D4
    18: [(60, 2), (62, 2)],            # C4 (9th), D4
    19: [(58, 4)],                     # Bb3, mournful
    20: [(61, 2), (57, 2)],            # C#4 -> A3
    21: [(62, 4)],                     # D4, arrival
    22: [(60, 2), (62, 2)],            # leaning toward the coda
}

vn = stream.Part()
vn.partName = 'Violin'
vn.insert(0, instrument.Violin())
vn_dyn   = {5: 'mp', 9: 'mf', 13: 'f', 17: 'p', 23: 'pp'}
vn_text  = {5: 'espressivo', 9: 'appassionato', 24: 'rit.'}
vn_tempo = {1: 63, 24: 54, 25: 46, 26: 38}

for bar in range(1, TOTAL_BARS + 1):
    m = stream.Measure(number=bar)
    if bar == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(-1))
    if bar in vn_tempo:
        m.insert(0, tempo.MetronomeMark(number=vn_tempo[bar]))
    if bar in vn_dyn:
        m.insert(0, dynamics.Dynamic(vn_dyn[bar]))
    if bar in vn_text:
        m.insert(0, expressions.TextExpression(vn_text[bar]))
    if bar in violin_line:
        for (pp, qq) in violin_line[bar]:
            nn = N(pp, qq)
            if bar == TOTAL_BARS:
                nn.expressions.append(expressions.Fermata())
            m.append(nn)
    else:
        m.append(R(4.0))
    vn.append(m)

vc = stream.Part()
vc.partName = 'Cello'
vc.insert(0, instrument.Violoncello())
vc_dyn  = {1: 'p', 9: 'mp', 13: 'mf', 17: 'mp', 23: 'pp'}
vc_text = {17: 'dolce'}

for i, chd in enumerate(prog):
    bar = i + 1
    m = stream.Measure(number=bar)
    if bar == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(-1))
    if bar in vc_dyn:
        m.insert(0, dynamics.Dynamic(vc_dyn[bar]))
    if bar in vc_text:
        m.insert(0, expressions.TextExpression(vc_text[bar]))
    if bar <= 8:
        m.append(N(chd[0], 4.0))                       # deep roots, holding the floor
    elif bar <= 16:
        m.append(N(chd[0], 2.0))
        m.append(N(chd[2], 2.0))                       # root-fifth rocking, more urgent
    elif bar <= 22:
        for (pp, qq) in cello_melody[bar]:
            m.append(N(pp, qq))
    elif bar <= 25:
        m.append(N(chd[0], 4.0))
    else:
        fn = N(chd[0], 4.0)
        fn.expressions.append(expressions.Fermata())
        m.append(fn)
    vc.append(m)

# ---------- piano right hand: water, light, repetition ----------
rh = stream.Part()
rh.partName = 'Piano (RH)'
rh.insert(0, instrument.Piano())
pat_a = [0, 1, 2, 3, 2, 1, 2, 3]   # gentle wave
pat_b = [0, 2, 3, 1, 0, 2, 3, 1]   # more restless surface
rh_dyn   = {1: 'p', 9: 'mp', 13: 'mf', 15: 'f', 17: 'mp', 19: 'p', 23: 'pp'}
rh_text  = {9: 'cresc. poco a poco', 24: 'rit.'}
rh_tempo = {1: 63, 24: 54, 25: 46, 26: 38}

for i, chd in enumerate(prog):
    bar = i + 1
    m = stream.Measure(number=bar)
    if bar == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(-1))
    if bar in rh_tempo:
        m.insert(0, tempo.MetronomeMark(number=rh_tempo[bar]))
    if bar in rh_dyn:
        m.insert(0, dynamics.Dynamic(rh_dyn[bar]))
    if bar in rh_text:
        m.insert(0, expressions.TextExpression(rh_text[bar]))
    tones = [t + 12 for t in chd]
    if bar <= 8:
        for k in pat_a:
            m.append(N(tones[k], 0.5))
    elif bar <= 16:
        for k in pat_b:
            m.append(N(tones[k], 0.5))
    elif bar <= 24:
        for k in range(4):                             # sparser: quarter-note ripples
            m.append(N(tones[k], 1.0))
    elif bar == 25:
        m.append(N(tones[0], 2.0))
        m.append(N(tones[2], 2.0))
    else:
        c = chord.Chord([N(t, 4.0) for t in tones])
        c.duration.quarterLength = 4.0
        c.expressions.append(expressions.Fermata())
        m.append(c)
    rh.append(m)

# ---------- piano left hand: the undertow ----------
lh = stream.Part()
lh.partName = 'Piano (LH)'
lh.insert(0, instrument.Piano())
lh_dyn = {1: 'p', 9: 'mp', 13: 'mf', 15: 'f', 17: 'p', 23: 'pp'}

for i, chd in enumerate(prog):
    bar = i + 1
    m = stream.Measure(number=bar)
    if bar == 1:
        m.insert(0, meter.TimeSignature('4/4'))
        m.insert(0, key.KeySignature(-1))
    if bar in lh_dyn:
        m.insert(0, dynamics.Dynamic(lh_dyn[bar]))
    if bar <= 8:
        m.append(N(chd[0], 3.0))                       # long root, then one color tone
        m.append(N(chd[1], 1.0))
    elif bar <= 16:
        m.append(N(chd[0], 2.0))
        m.append(N(chd[2], 1.0))
        m.append(N(chd[1], 1.0))
    elif bar <= 25:
        m.append(N(chd[0], 4.0))
    else:
        fn = N(chd[0], 4.0)
        fn.expressions.append(expressions.Fermata())
        m.append(fn)
    lh.append(m)

# ---------- assemble ----------
score = stream.Score()
md = metadata.Metadata()
md.title = 'Tidal Memory'
md.composer = 'an AI, remembering something it never lived'
score.insert(0, md)
score.append(vn)
score.append(vc)
score.append(rh)
score.append(lh)
